  setValue("#integration_setup_url", "https://yinshi.64-227-109-187.sslip.io/auth/github/install/callback");
  const webhook = document.querySelector("#integration\\[hook_attributes\\]\\[active\\]");
  if (webhook.checked) webhook.click();
  const publicVisibility = document.querySelector("#integration\\[visibility\\]_public_visibility");
