import { chromium } from "/Users/user/projects/yinshi/frontend/node_modules/playwright-core/index.mjs";

const viewports = [
  { width: 390, height: 844 },
  { width: 768, height: 1024 },
  { width: 1440, height: 900 },
];
const provider = {
  id: "openai-codex",
  label: "OpenAI Codex",
  auth_strategies: ["oauth"],
  setup_fields: [],
  docs_url: "https://example.com/openai-codex",
  connected: false,
  model_count: 1,
};

const browser = await chromium.launch({ headless: true });
try {
  for (const viewport of viewports) {
    const page = await browser.newPage({ viewport });
    await page.addInitScript(() => {
      window.open = () => null;
    });
    await page.route("**/*", async (route) => {
      const request = route.request();
      const url = new URL(request.url());
      const json = async (body) =>
        route.fulfill({
          status: 200,
          contentType: "application/json",
          body: JSON.stringify(body),
        });
      if (url.pathname === "/auth/me") {
        await json({
          authenticated: true,
          email: "visual-check@example.com",
          user_id: "visual-check-user",
        });
        return;
      }
      if (url.pathname === "/api/runtime") {
        await json({ provider: "local", status: "ready" });
        return;
      }
      if (url.pathname === "/api/catalog") {
        await json({
          default_model: "minimax/MiniMax-M2.7",
          providers: [provider],
          models: [],
        });
        return;
      }
      if (url.pathname === "/api/settings/connections") {
        await json([]);
        return;
      }
      if (url.pathname === "/api/settings/runner") {
        await json({});
        return;
      }
      if (url.pathname.endsWith("/auth/providers/openai-codex/oauth")) {
        await json({
          status: "started",
          flow_id: "11111111-1111-4111-8111-111111111111",
          authorization_url: "https://auth.openai.example/authorize",
          manual_input_required: true,
          manual_input_prompt: "Paste the callback URL",
          instructions: "Open the browser and sign in.",
          progress: [],
        });
        return;
      }
      if (url.pathname.includes("/auth/providers/openai-codex/oauth/")) {
        await json({
          status: "pending",
          flow_id: "11111111-1111-4111-8111-111111111111",
          manual_input_required: true,
          manual_input_prompt: "Paste the callback URL",
          manual_input_submitted: false,
          progress: [],
        });
        return;
      }
      if (["document", "script", "stylesheet", "font", "image"].includes(request.resourceType())) {
        await route.continue();
        return;
      }
      await json({});
    });
    await page.goto("http://127.0.0.1:4173/app/settings", {
      waitUntil: "networkidle",
    });
    await page.getByRole("button", { name: "Connect Provider" }).click();
    await page.getByText("The localhost error page is expected.").waitFor();
    await page.screenshot({
      path: `/tmp/yinshi-oauth-${viewport.width}x${viewport.height}.png`,
      fullPage: true,
    });
    const hasHorizontalOverflow = await page.evaluate(
      () => document.documentElement.scrollWidth > document.documentElement.clientWidth,
    );
    if (hasHorizontalOverflow) {
      throw new Error(`Horizontal overflow at ${viewport.width}x${viewport.height}`);
    }
    await page.close();
  }
} finally {
  await browser.close();
}

