import { readFileSync } from "node:fs";
import { chromium } from "/Users/user/projects/yinshi/frontend/node_modules/playwright-core/index.mjs";
const session = readFileSync("/tmp/yinshi-model-test-session", "utf8").trim();
const browser = await chromium.launch({ headless: true });
let passed = false;
try {
  const context = await browser.newContext();
  await context.addCookies([{ name: "yinshi_session", value: session, domain: "yinshi.io", path: "/", secure: true, httpOnly: true, sameSite: "Lax" }]);
  const page = await context.newPage();
  await page.goto("https://yinshi.io/app/session/fe15629ff060ed51a53c335eb59d4240", { waitUntil: "networkidle", timeout: 120000 });
  const input = page.getByPlaceholder("Describe what to build...");
  await input.waitFor({ state: "visible", timeout: 120000 });
  await input.fill("Reply with exactly YINSHI_OAI_OK and nothing else.");
  await page.getByRole("button", { name: "Send", exact: true }).click();
  await page.getByText("YINSHI_OAI_OK", { exact: true }).waitFor({ state: "visible", timeout: 240000 });
  passed = true;
  await context.close();
} catch {
  passed = false;
} finally {
  await browser.close();
}
if (!passed) process.exit(1);
console.log("openai_model_prompt=passed");

