  if (method === "DELETE" && terminalMember) {
    return "terminal";
  }
  const providerCollection = path === "/api/settings/connections";
  const providerMember = PROVIDER_CONNECTION_MEMBER_PATH.test(path);
  if ((method === "GET" || method === "POST") && providerCollection) {
