  if (method === "POST" && PROVIDER_AUTH_START_PATH.test(path)) {
    return "provider.configure";
  }
  if (
    (method === "GET" || method === "POST") &&
    PROVIDER_AUTH_CALLBACK_PATH.test(path)
  ) {
    return "provider.configure";
  }
  if (
    (method === "GET" || method === "DELETE") &&
    path === "/api/settings/pi-config"
  ) {
    return "pi.configure";
  }
  if (
